CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT );
CREATE TABLE IF NOT EXISTS usuarios ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, email TEXT NOT NULL UNIQUE, senha TEXT NOT NULL, papel TEXT NOT NULL DEFAULT 'admin', ativo INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS sessoes ( token TEXT PRIMARY KEY, usuario_id INTEGER NOT NULL, expira_em TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_sessoes_user ON sessoes(usuario_id);
CREATE TABLE IF NOT EXISTS planos ( id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, tipo TEXT NOT NULL DEFAULT 'dieta', dias INTEGER NOT NULL DEFAULT 30, preco_brl REAL DEFAULT 0, preco_usd REAL DEFAULT 0, consultas INTEGER DEFAULT 0, follow_up_dias INTEGER DEFAULT 0, renova_auto INTEGER NOT NULL DEFAULT 0, regras TEXT, ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0 );
CREATE TABLE IF NOT EXISTS parceiros ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, contato TEXT, obs TEXT, ativo INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS pacientes ( id INTEGER PRIMARY KEY AUTOINCREMENT, cod TEXT, nome TEXT NOT NULL, apelido TEXT, pais TEXT DEFAULT 'Brasil', email TEXT, telefone TEXT, instagram TEXT, nascimento TEXT, cpf TEXT, profissao TEXT, endereco TEXT, objetivo TEXT, status TEXT NOT NULL DEFAULT 'ativo', parceiro_id INTEGER, indicacao TEXT, obs TEXT, sexo TEXT, altura_cm REAL, fuso TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), cidade TEXT, form_token TEXT, inbody_ativo INTEGER NOT NULL DEFAULT 0, inbody_modelo TEXT, inbody_plano TEXT );
CREATE INDEX IF NOT EXISTS idx_pac_cod ON pacientes(cod);
CREATE INDEX IF NOT EXISTS idx_pac_status ON pacientes(status);
CREATE INDEX IF NOT EXISTS idx_pac_nome ON pacientes(nome);
CREATE TABLE IF NOT EXISTS contratos ( id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER NOT NULL, plano_id INTEGER, codigo_plano TEXT, data_inicial TEXT, data_final TEXT, valor_cobrado REAL DEFAULT 0, moeda TEXT DEFAULT 'BRL', forma TEXT, qtd_parcelas INTEGER DEFAULT 1, status TEXT DEFAULT 'ativo', obs TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_con_pac ON contratos(paciente_id);
CREATE TABLE IF NOT EXISTS parcelas ( id INTEGER PRIMARY KEY AUTOINCREMENT, contrato_id INTEGER NOT NULL, paciente_id INTEGER NOT NULL, numero INTEGER NOT NULL DEFAULT 1, total INTEGER NOT NULL DEFAULT 1, valor REAL NOT NULL DEFAULT 0, moeda TEXT NOT NULL DEFAULT 'BRL', vencimento TEXT, status TEXT NOT NULL DEFAULT 'aberta', pago REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_par_pac ON parcelas(paciente_id);
CREATE INDEX IF NOT EXISTS idx_par_venc ON parcelas(vencimento, status);
CREATE TABLE IF NOT EXISTS pagamentos ( id INTEGER PRIMARY KEY AUTOINCREMENT, parcela_id INTEGER, paciente_id INTEGER NOT NULL, data TEXT NOT NULL, valor REAL NOT NULL, moeda TEXT NOT NULL DEFAULT 'BRL', cotacao REAL NOT NULL DEFAULT 1, valor_brl REAL NOT NULL DEFAULT 0, forma TEXT, obs TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_pag_data ON pagamentos(data);
CREATE INDEX IF NOT EXISTS idx_pag_pac ON pagamentos(paciente_id);
CREATE TABLE IF NOT EXISTS cotacoes ( dia TEXT NOT NULL, moeda TEXT NOT NULL, taxa REAL NOT NULL, fonte TEXT DEFAULT 'awesomeapi', PRIMARY KEY (dia, moeda) );
CREATE TABLE IF NOT EXISTS anamneses ( id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER, cod TEXT, nome TEXT, email TEXT, telefone TEXT, respondido_em TEXT, origem TEXT DEFAULT 'BR', dados TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_ana_pac ON anamneses(paciente_id);
CREATE INDEX IF NOT EXISTS idx_ana_nome ON anamneses(nome);
CREATE TABLE IF NOT EXISTS consultas ( id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER NOT NULL, data TEXT NOT NULL, peso_kg REAL, peso_lbs REAL, treino TEXT, cafe TEXT, lanche_manha TEXT, almoco TEXT, lanche_tarde TEXT, jantar TEXT, ceia TEXT, observacoes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), refeicoes TEXT, objetivo TEXT, tmb REAL, get_kcal REAL, fator_atividade REAL );
CREATE INDEX IF NOT EXISTS idx_cons_pac ON consultas(paciente_id, data);
CREATE TABLE IF NOT EXISTS compromissos ( id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, tipo TEXT NOT NULL DEFAULT 'consulta', paciente_id INTEGER, inicio TEXT NOT NULL, fim TEXT, dia_todo INTEGER NOT NULL DEFAULT 0, local TEXT, obs TEXT, status TEXT NOT NULL DEFAULT 'marcado', created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_comp_inicio ON compromissos(inicio);
CREATE TABLE IF NOT EXISTS lista_espera ( id INTEGER PRIMARY KEY AUTOINCREMENT, cod TEXT, nome TEXT, idade TEXT, pais TEXT, situacao TEXT, obs TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
INSERT OR IGNORE INTO planos (codigo,nome,tipo,dias,consultas,follow_up_dias,posicao) VALUES ('30D','Dieta 30 dias','dieta',30,1,7,1), ('30T','Treino 30 dias','treino',30,1,7,2), ('30DT','Dieta + Treino 30 dias','dieta_treino',30,1,7,3), ('30LE','Low Energy 30 dias','le',30,1,7,4), ('90D','Dieta 90 dias','dieta',90,3,7,5), ('90T','Treino 90 dias','treino',90,3,7,6), ('90DT','Dieta + Treino 90 dias','dieta_treino',90,3,7,7), ('semestral','Semestral','dieta_treino',180,6,7,8), ('anual','Anual','dieta_treino',365,12,7,9), ('personalizado','Personalizado','outro',30,0,0,10);
INSERT OR IGNORE INTO settings (key,value) VALUES ('fuso','America/Sao_Paulo'), ('followup_dias_alerta','10'), ('vencimento_alerta_dias','30'), ('moedas','BRL,USD,GBP,EUR');
CREATE TABLE IF NOT EXISTS negociacoes ( id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER NOT NULL, tipo TEXT NOT NULL DEFAULT 'novo', etapa TEXT NOT NULL DEFAULT 'novo', origem TEXT, call_em TEXT, proximo_contato TEXT, motivo TEXT, plano_id INTEGER, valor_previsto REAL DEFAULT 0, moeda TEXT DEFAULT 'BRL', contrato_id INTEGER, contrato_origem INTEGER, obs TEXT, fechado_em TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_neg_etapa ON negociacoes(tipo, etapa);
CREATE INDEX IF NOT EXISTS idx_neg_pac ON negociacoes(paciente_id);
CREATE INDEX IF NOT EXISTS idx_neg_prox ON negociacoes(proximo_contato);
CREATE INDEX IF NOT EXISTS idx_neg_call ON negociacoes(call_em);
CREATE UNIQUE INDEX IF NOT EXISTS idx_neg_renov ON negociacoes(contrato_origem) WHERE contrato_origem IS NOT NULL;
CREATE TABLE IF NOT EXISTS interacoes ( id INTEGER PRIMARY KEY AUTOINCREMENT, negociacao_id INTEGER, paciente_id INTEGER NOT NULL, tipo TEXT NOT NULL DEFAULT 'nota', data TEXT NOT NULL, resultado TEXT, obs TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_int_neg ON interacoes(negociacao_id);
CREATE INDEX IF NOT EXISTS idx_int_pac ON interacoes(paciente_id, data);
CREATE TABLE IF NOT EXISTS motivos_perda ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL UNIQUE, aplica TEXT NOT NULL DEFAULT 'ambos', ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0 );
INSERT OR IGNORE INTO motivos_perda (nome,aplica,posicao) VALUES ('Preço','ambos',1), ('Vai pensar / sumiu','ambos',2), ('Sem tempo agora','ambos',3), ('Foi com outro profissional','ambos',4), ('Não era o perfil','novo',5), ('Não respondeu','ambos',6), ('Atingiu o objetivo','renovacao',7), ('Insatisfeito com o resultado','renovacao',8);
INSERT OR IGNORE INTO settings (key,value) VALUES ('renovacao_antecedencia','30'), ('origens','Direct,Indicação,Formulário,Anúncio,Outro');
INSERT OR IGNORE INTO settings (key,value) VALUES ('fatores_f','Sedentário:1.40|Leve:1.55|Moderado:1.70|Intenso:2.00'), ('fatores_m','Sedentário:1.40|Leve:1.56|Moderado:1.78|Intenso:2.10');
CREATE TABLE IF NOT EXISTS wa_templates ( id INTEGER PRIMARY KEY AUTOINCREMENT, chave TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, modo TEXT NOT NULL DEFAULT 'semi', evento TEXT, corpo TEXT NOT NULL, antecedencia_h REAL DEFAULT 0, hora_envio TEXT DEFAULT '09:00', ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS wa_fila ( id INTEGER PRIMARY KEY AUTOINCREMENT, chave_unica TEXT UNIQUE, paciente_id INTEGER, template_chave TEXT, telefone TEXT NOT NULL, mensagem TEXT NOT NULL, agendado_para TEXT, status TEXT NOT NULL DEFAULT 'agendado', modo TEXT NOT NULL DEFAULT 'auto', ref_tipo TEXT, ref_id INTEGER, erro TEXT, enviado_em TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_wa_status ON wa_fila(status, agendado_para);
CREATE INDEX IF NOT EXISTS idx_wa_pac ON wa_fila(paciente_id, created_at);
INSERT OR IGNORE INTO settings (key,value) VALUES ('wa_url',''), ('wa_apikey',''), ('wa_instancia',''), ('wa_ativo','0'), ('wa_token_cron',''), ('wa_janela_ini','08:00'), ('wa_janela_fim','20:00'), ('fusos_pais','Brasil:America/Sao_Paulo|US:America/New_York|Portugal:Europe/Lisbon|Inglaterra:Europe/London|Canadá:America/Toronto|Colômbia:America/Bogota|Luxemburgo:Europe/Luxembourg|Tchéquia:Europe/Prague');
INSERT OR IGNORE INTO wa_templates (chave,nome,modo,evento,corpo,antecedencia_h,hora_envio,posicao) VALUES ('call_lembrete','Lembrete de call','auto','call','Oi {primeiro_nome}! Passando pra confirmar nossa call de hoje às {hora_call}. Tudo certo pra você?',3,'',1), ('cobranca_previa','Cobrança — 3 dias antes','auto','parcela_previa','Oi {primeiro_nome}! Sua parcela {parcela} de {valor} vence em {vencimento}. Qualquer dúvida é só me chamar.',72,'09:00',2), ('cobranca_hoje','Cobrança — no dia','auto','parcela_hoje','Oi {primeiro_nome}! Hoje vence a parcela {parcela} de {valor}. Me avisa quando fizer que eu já dou baixa.',0,'09:00',3), ('cobranca_atraso','Cobrança — em atraso','auto','parcela_atraso','Oi {primeiro_nome}, tudo bem? A parcela {parcela} de {valor} venceu em {vencimento} e ainda não identifiquei. Deu algum problema no pagamento?',48,'09:00',4), ('renovacao_aviso','Renovação — 15 dias antes','auto','renovacao','Oi {primeiro_nome}! Seu plano {plano} termina em {data_fim}. Vamos falar sobre os próximos passos? Me diz um horário que funciona pra você.',360,'10:00',5), ('checkin_diario','Check-in diário da rotina','auto','checkin','Bom dia {primeiro_nome}! Como foi a rotina de ontem? Me conta o treino, as refeições e como você se sentiu.',0,'08:00',6), ('followup_venda','Follow-up de venda','semi','','Oi {primeiro_nome}! Como combinamos, estou passando pra retomar nossa conversa sobre a consultoria. Seguimos?',0,'',10), ('boas_vindas','Boas-vindas ao fechar','semi','','{primeiro_nome}, seja muito bem-vindo! Seu plano {plano} começa agora e vai até {data_fim}. Vou te mandar os próximos passos por aqui.',0,'',11), ('pedir_retorno','Pedir retorno do paciente','semi','','Oi {primeiro_nome}! Faz um tempo que não recebo notícias suas. Como está indo?',0,'',12), ('cobranca_manual','Cobrança manual','semi','','Oi {primeiro_nome}! Passando pra lembrar da parcela {parcela} de {valor}, vencimento {vencimento}.',0,'',13);
INSERT OR IGNORE INTO settings (key,value) VALUES ('form_titulo','Anamnese — Luca Ternes'), ('form_intro','Preencha com calma. São essas informações que eu uso para montar o seu plano antes da nossa call.'), ('form_agradecimento','Recebi tudo. Vou analisar suas respostas e te chamo no WhatsApp para marcarmos a call.');
CREATE TABLE IF NOT EXISTS anexos ( id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER NOT NULL, tipo TEXT NOT NULL DEFAULT 'dieta', titulo TEXT, data_ref TEXT, obs TEXT, arquivo_nome TEXT NOT NULL, chave TEXT NOT NULL, mime TEXT, tamanho INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_anexo_pac ON anexos(paciente_id, data_ref);
CREATE INDEX IF NOT EXISTS idx_anexo_tipo ON anexos(tipo);
CREATE INDEX IF NOT EXISTS idx_pac_token ON pacientes(form_token);
CREATE TABLE IF NOT EXISTS objetivos ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL UNIQUE, nome_en TEXT, nome_es TEXT, ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0 );
INSERT OR IGNORE INTO objetivos (nome,nome_en,nome_es,posicao) VALUES ('Emagrecimento','Weight loss','Pérdida de peso',1), ('Definição muscular','Muscle definition','Definición muscular',2), ('Ganho de massa muscular','Muscle gain','Ganancia de masa muscular',3), ('Manutenção do peso','Weight maintenance','Mantenimiento del peso',4);
CREATE TABLE IF NOT EXISTS form_blocos ( id INTEGER PRIMARY KEY AUTOINCREMENT, chave TEXT NOT NULL UNIQUE, titulo_pt TEXT NOT NULL, titulo_en TEXT, titulo_es TEXT, ajuda_pt TEXT, ajuda_en TEXT, ajuda_es TEXT, ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0 );
CREATE TABLE IF NOT EXISTS form_campos ( id INTEGER PRIMARY KEY AUTOINCREMENT, bloco_chave TEXT NOT NULL, chave TEXT NOT NULL UNIQUE, tipo TEXT NOT NULL DEFAULT 'texto', rot_pt TEXT NOT NULL, rot_en TEXT, rot_es TEXT, dica_pt TEXT, dica_en TEXT, dica_es TEXT, opcoes_pt TEXT, opcoes_en TEXT, opcoes_es TEXT, obrigatorio INTEGER NOT NULL DEFAULT 1, ativo INTEGER NOT NULL DEFAULT 1, posicao INTEGER DEFAULT 0 );
CREATE INDEX IF NOT EXISTS idx_fcampo_bloco ON form_campos(bloco_chave, posicao);
INSERT OR IGNORE INTO form_blocos (chave,titulo_pt,titulo_en,titulo_es,ajuda_pt,ajuda_en,ajuda_es,posicao) VALUES ('quem','Quem é você','About you','Quién eres','Para eu saber com quem estou falando.','So I know who I am talking to.','Para saber con quién estoy hablando.',1), ('objetivo','Objetivo e medidas','Goal and measurements','Objetivo y medidas','O ponto de partida.','The starting point.','El punto de partida.',2), ('saude','Saúde','Health','Salud','Seja específico — é o que me impede de errar.','Be specific — this is what keeps me from getting it wrong.','Sé específico: es lo que evita que yo me equivoque.',3), ('treino','Treino','Training','Entrenamiento','Para eu encaixar a alimentação no seu dia.','So I can fit your meals into your day.','Para encajar tu alimentación en tu día.',4), ('rotina','Sua rotina','Your routine','Tu rutina','Os horários de verdade, não os ideais.','The real times, not the ideal ones.','Los horarios reales, no los ideales.',5), ('combinado','Combinado','Agreement','Acuerdo','Duas confirmações antes de começarmos.','Two confirmations before we start.','Dos confirmaciones antes de empezar.',6);
INSERT OR IGNORE INTO form_campos (bloco_chave,chave,tipo,rot_pt,rot_en,rot_es,dica_pt,dica_en,dica_es,opcoes_pt,opcoes_en,opcoes_es,obrigatorio,posicao) VALUES ('quem','nome','texto','Nome completo','Full name','Nombre completo','','','','','','',1,1), ('quem','email','email','E-mail','Email','Correo electrónico','','','','','','',1,2), ('quem','telefone','tel','WhatsApp com DDI e DDD','WhatsApp with country code','WhatsApp con código de país','Ex.: +55 51 99999-9999 ou +1 212 555-0000','E.g. +1 212 555-0000','Ej.: +34 600 000 000','','','',1,3), ('quem','pais','pais','Onde você mora','Where you live','Dónde vives','','','','','','',1,4), ('quem','cidade','texto','Cidade','City','Ciudad','Uso para acertar o fuso horário das nossas conversas.','I use this to get your time zone right.','Lo uso para ajustar tu huso horario.','','','',1,5), ('quem','instagram','texto','Instagram','Instagram','Instagram','','','','','','',1,6), ('quem','nascimento','data','Data de nascimento','Date of birth','Fecha de nacimiento','','','','','','',1,7), ('quem','profissao','texto','Profissão','Occupation','Profesión','','','','','','',1,8), ('quem','indicacao','texto','Alguém indicou meu trabalho? Quem?','Did someone refer me to you? Who?','¿Alguien te recomendó mi trabajo? ¿Quién?','Se ninguém indicou, escreva "ninguém".','If nobody did, write "nobody".','Si nadie lo hizo, escribe "nadie".','','','',1,9), ('objetivo','objetivo','objetivo','Seu principal objetivo','Your main goal','Tu objetivo principal','','','','','','',1,10), ('objetivo','plano_codigo','plano','Plano de interesse','Plan you are interested in','Plan que te interesa','','','','','','',1,11), ('objetivo','sexo','radio','Sexo','Sex','Sexo','','','','Feminino|Masculino','Female|Male','Femenino|Masculino',1,12), ('objetivo','peso_kg','peso','Peso','Weight','Peso','','','','','','',1,13), ('objetivo','altura_cm','altura','Altura','Height','Altura','','','','','','',1,14), ('saude','doenca','longo','Tem alguma doença (hipertensão, diabetes, tireoide, lipedema, SOP)? Faz uso de medicação, qual?','Any medical condition (high blood pressure, diabetes, thyroid, lipedema, PCOS)? Any medication?','¿Tienes alguna enfermedad (hipertensión, diabetes, tiroides, lipedema, SOP)? ¿Tomas alguna medicación?','Se não tiver nada, escreva "não".','If none, write "no".','Si no tienes nada, escribe "no".','','','',1,15), ('saude','restricao_alimentar','longo','Restrição, alergia, intolerância ou alimento que quer evitar? Qual e com que intensidade?','Any restriction, allergy, intolerance or food you want to avoid? Which one and how severe?','¿Alguna restricción, alergia, intolerancia o alimento que quieras evitar? ¿Cuál y con qué intensidad?','Se não tiver nada, escreva "não".','If none, write "no".','Si no tienes nada, escribe "no".','','','',1,16), ('saude','intestino','radio','Como é o seu intestino?','How are your bowel movements?','¿Cómo es tu tránsito intestinal?','','','','Normal|Constipado (fezes ressecadas, de difícil evacuação e não regulares)|Diarreia constante','Normal|Constipated (hard, difficult, irregular)|Frequent diarrhea','Normal|Estreñido (heces secas, difíciles e irregulares)|Diarrea frecuente',1,17), ('saude','agua','texto','Quantos litros de água pura você bebe por dia?','How much plain water do you drink per day?','¿Cuántos litros de agua pura bebes al día?','','','','','','',1,18), ('saude','suplementos','longo','Já usou ou usa suplementos? Qual, quando e em que dose?','Have you used or do you use supplements? Which, when and what dose?','¿Has usado o usas suplementos? ¿Cuál, cuándo y en qué dosis?','Se nunca usou, escreva "não".','If never, write "no".','Si nunca, escribe "no".','','','',1,19), ('saude','suplemento_incluir','texto','Se não usa hoje, quer incluir no plano?','If you do not use any, would you like to include them?','Si hoy no usas, ¿quieres incluirlos en el plan?','','','','','','',1,20), ('saude','peptideo','longo','Já usou ou usa peptídeo? Qual, quando e em que dose?','Have you used or do you use peptides? Which, when and what dose?','¿Has usado o usas péptidos? ¿Cuál, cuándo y en qué dosis?','Se nunca usou, escreva "não".','If never, write "no".','Si nunca, escribe "no".','','','',1,21), ('saude','restricao_fisica','longo','Tem alguma restrição física? Qual?','Any physical limitation? Which?','¿Tienes alguna limitación física? ¿Cuál?','Se não tiver nada, escreva "não".','If none, write "no".','Si no tienes nada, escribe "no".','','','',1,22), ('treino','atividade','texto','Qual atividade física você pratica ou quer praticar?','What physical activity do you do or want to do?','¿Qué actividad física practicas o quieres practicar?','','','','','','',1,23), ('treino','frequencia','texto','Quantas vezes por semana?','How many times per week?','¿Cuántas veces por semana?','','','','','','',1,24), ('treino','horario_treino','texto','Que horas você treina ou pretende treinar?','What time do you train or plan to train?','¿A qué hora entrenas o piensas entrenar?','','','','','','',1,25), ('treino','segunda_atividade','longo','Faz uma segunda atividade no dia? Conte qual e em que horário.','Do you do a second activity in the day? Tell me which and when.','¿Haces una segunda actividad al día? Cuéntame cuál y a qué hora.','Se não fizer, escreva "não".','If not, write "no".','Si no, escribe "no".','','','',1,26), ('rotina','acorda','hora','Que horas acorda','Wake up time','A qué hora te levantas','','','','','','',1,27), ('rotina','cafe','hora','Café da manhã','Breakfast','Desayuno','','','','','','',1,28), ('rotina','almoco','hora','Almoço','Lunch','Almuerzo','','','','','','',1,29), ('rotina','lanche','hora','Lanche','Snack','Merienda','','','','','','',1,30), ('rotina','jantar','hora','Jantar','Dinner','Cena','','','','','','',1,31), ('rotina','dorme','hora','Que horas dorme','Bedtime','A qué hora te acuestas','','','','','','',1,32), ('rotina','pref_jantar','radio','Sua preferência no jantar','Your preference for dinner','Tu preferencia para la cena','','','','Comida como no almoço (ex.: arroz e frango)|Lanche como no café da manhã (ex.: pão com ovo)','A full meal like lunch (e.g. rice and chicken)|A light meal like breakfast (e.g. eggs on toast)','Comida como el almuerzo (ej.: arroz con pollo)|Algo ligero como el desayuno (ej.: pan con huevo)',1,33), ('rotina','manter','longo','Algum alimento que você faz questão de manter no plano? Qual?','Any food you really want to keep in your plan? Which?','¿Algún alimento que quieras mantener sí o sí en el plan? ¿Cuál?','Se não tiver, escreva "não".','If none, write "no".','Si no, escribe "no".','','','',1,34), ('rotina','relevante','longo','Tem algum detalhe que você acha importante eu saber?','Anything else you think I should know?','¿Hay algo más que creas importante que yo sepa?','Se não tiver, escreva "não".','If none, write "no".','Si no, escribe "no".','','','',1,35), ('combinado','ciente_rotina','radio','Você está ciente de que precisará me passar sua rotina pelo WhatsApp diariamente?','Do you understand that you will need to send me your daily routine on WhatsApp?','¿Entiendes que tendrás que pasarme tu rutina por WhatsApp todos los días?','','','','Sim|Não','Yes|No','Sí|No',1,36), ('combinado','ciente_texto','radio','Tenho uma limitação auditiva severa e tenho dificuldade com áudios no WhatsApp. Posso contar com você para mandar as mensagens em texto?','I have severe hearing loss and struggle with voice notes on WhatsApp. Can I count on you to send text messages?','Tengo una pérdida auditiva severa y me cuesta escuchar audios en WhatsApp. ¿Puedo contar contigo para que escribas los mensajes?','','','','Sim|Não','Yes|No','Sí|No',1,37);
